body:
Hi,

I had a script that I run daily to push some scheduled messages to some bots to trigger them accomplish some periodical tasks.

Here is my final code that worked until v8.8.9

`<?php

$sessionPath = 'session.madeline';
$apiId       = ****;
$apiHash     = '********';
$phoneNumber = '+********';

$chatId  = '@****bot';
$chatId2 = '@****bot';
$chatId3 = '@****bot';

$messages = [
/*
    ['hour' => **, 'minute' => **, 'second' => **,  'message' => '********'],
*/
];

$messages2 = [
/*
    ['hour' => **, 'minute' => **, 'second' => **,  'message' => '********'],
*/
];

if (file_exists('madeline-8.8.9.phar')) {
    require 'madeline-8.8.9.phar';
    echo "MadelineProto 8.8.9 (local phar).\n";
} else {
    if (!file_exists('madeline.php')) {
        copy('https://phar.madelineproto.xyz/madeline.php', 'madeline.php');
    }
    require 'madeline.php';
    echo "MadelineProto loaded.\n";
}

use danog\MadelineProto\API;
use danog\MadelineProto\Settings;
use danog\MadelineProto\Settings\AppInfo;
use danog\MadelineProto\Settings\Connection;

$settings = new Settings();

$appInfo = (new AppInfo())
    ->setApiId($apiId)
    ->setApiHash($apiHash);
$settings->setAppInfo($appInfo);

$connection = new Connection();
$connection->setTimeout(30.0);
$settings->setConnection($connection);

$MadelineProto = new API($sessionPath, $settings);
$MadelineProto->start();

if (!$MadelineProto->getSelf()) {
    $MadelineProto->phoneLogin($phoneNumber);
    $MadelineProto->completePhoneLogin($code);
}

function schedule_message($MadelineProto, $chatId, $message, $timestamp) {
    try {
        $MadelineProto->messages->sendMessage([
            'peer'          => $chatId,
            'message'       => $message,
            'schedule_date' => $timestamp
        ]);
        echo "Planned: " . date('Y-m-d H:i:s', $timestamp) . " → $chatId : $message\n";
    } catch (\Exception $e) {
        echo "ERR ({$chatId} - " . date('Y-m-d H:i:s', $timestamp) . "): " . $e->getMessage() . "\n";
    }
}

$nextMonday = strtotime('today');
$nextFriday = strtotime('today', $nextMonday);

$today = time();

for ($day = $nextMonday; $day <= $nextFriday; $day = strtotime('+1 day', $day)) {
    foreach ($messages as $msg) {
        $timestamp = mktime($msg['hour'], $msg['minute'], $msg['second'], date('n', $day), date('j', $day), date('Y', $day));

        if ($timestamp <= $today) {
            echo "Skipping, past: " . date('Y-m-d H:i:s', $timestamp) . " → {$msg['message']}\n";
            continue;
        }

        schedule_message($MadelineProto, $chatId,  $msg['message'], $timestamp);
        usleep(300000);
    }
}
`

